     2→
     3→use std::type_name::{Self, TypeName};
     4→use sui::dynamic_field;
     5→use sui::package;
     6→use sui::table::{Self, Table};
     7→use sui::clock::Clock;
     8→
     9→use pyth::price_info::PriceInfoObject;
    10→
    11→use x_oracle::price_feed::{Self, PriceFeed, PriceFeedComponent};
    12→use x_oracle::pyth_adaptor::{Self, PythFeedData};
    13→use x_oracle::oracle_error; 
    14→
    15→public struct AdminCap has key, store {
    16→    id: UID,
    17→}
    18→
    19→public struct X_ORACLE has drop {}
    20→
    21→// This tracks the list of base tokens for oracle price feed quotes. 
    22→// Given different base token, the price feed might be created differently. For example,
    23→// lstSui vs Sui will have a different price feed reporting mechanism compared to say 
    24→// lstSui vs USD.
    25→public struct BaseToken has drop, copy, store {
    26→    id: u8,
    27→}
    28→
    29→const CURRENT_VERSION: u64 = 0;
    30→const MAX_DELAY_TOLERANCE_MS: u64 = 1800000;
    31→
    32→const USD: u8 = 0;
    33→// const SUI: u8 = 1;
    34→
    35→
    36→public struct XOracle has key {
    37→    id: UID,
    38→
    39→    price_delay_tolerance_ms: u64,
    40→    prices: Table<BaseToken, Table<TypeName, PriceFeed>>,
    41→
    42→    version: u64,
    43→
    44→    // dynamic fields:
    45→    // - pyth_price_feeds: Table<TypeName, PythFeedData>
    46→}
    47→
    48→fun init(otw: X_ORACLE, ctx: &mut TxContext) {
    49→    package::claim_and_keep(otw, ctx);
    50→
    51→    let x_oracle = new(ctx);
    52→    transfer::share_object(x_oracle);
    53→
    54→    let admin_cap = AdminCap { id: object::new(ctx) };
    55→    transfer::transfer(admin_cap, ctx.sender());
    56→}
    57→
    58→fun new(ctx: &mut TxContext): XOracle {
    59→    let mut x_oracle = XOracle {
    60→        id: object::new(ctx),
    61→        prices: table::new(ctx),
    62→        // default delay is 5 seconds
    63→        price_delay_tolerance_ms: 5000,
    64→        version: CURRENT_VERSION,
    65→    };
    66→
    67→    x_oracle.prices.add(usd(), table::new(ctx));
    68→
    69→    let pyth_price_feeds: Table<TypeName, PythFeedData> = table::new(ctx);
    70→    dynamic_field::add(&mut x_oracle.id, PythPriceFeedKey {}, pyth_price_feeds);
    71→
    72→    x_oracle
    73→}
    74→
    75→public fun usd(): BaseToken { BaseToken { id: USD } }
    76→// public(package) fun sui(): BaseToken { BaseToken { id: SUI } }
    77→
    78→public fun base_token_from_u8(id: u8): BaseToken {
    79→    match (id) {
    80→        USD => usd(),
    81→        _ => {
    82→            abort x_oracle::oracle_error::unknown_oracle_base_token()
    83→        }
    84→    }
    85→}
    86→
    87→public fun price(self: &XOracle, coin_type: TypeName, base_token: BaseToken): &PriceFeed { 
    88→    let BaseToken { id } = base_token;
    89→
    90→    match (id) {
    91→        USD => usd_price(self, coin_type),
    92→        _ => {
    93→            abort x_oracle::oracle_error::unknown_oracle_base_token()
    94→        }
    95→    }
    96→}
    97→
    98→public(package) fun ensure_version_matches(self: &XOracle) {
    99→    assert!(self.version == CURRENT_VERSION, oracle_error::version_not_match());
   100→}
   101→
   102→public(package) fun migrate(self: &mut XOracle): u64 {
   103→    // only sequential migrate is allowed
   104→    assert!(self.version < CURRENT_VERSION, oracle_error::version_not_match());
   105→    self.version = CURRENT_VERSION;
   106→
   107→    CURRENT_VERSION
   108→}
   109→
   110→// refresh pyth price feed, note that we are updating against usd prices
   111→public(package) fun refresh_usd_price<CoinType>(
   112→    x_oracle: &mut XOracle,
   113→    price_info_object: &PriceInfoObject,
   114→    clock: &Clock,
   115→) {
   116→    let pyth_feed_infos = x_oracle.pyth_price_feeds();
   117→
   118→    let coin_type = type_name::with_defining_ids<CoinType>();
   119→    let feed_data = pyth_feed_infos.borrow(coin_type);
   120→
   121→    // Make sure the price info object is the registerred one for the coin type
   122→    feed_data.assert_pyth_price_info_object(price_info_object);
   123→
   124→    let (ema, spot) = pyth_adaptor::get_pyth_price(price_info_object, feed_data, clock);
   125→
   126→    update_price_feed(
   127→        x_oracle,
   128→
   129→        usd(),
   130→        coin_type,
   131→
   132→        spot,
   133→        ema,
   134→    );
   135→}
   136→
   137→public(package) fun price_delay_tolerance_ms(self: &XOracle): u64 { self.price_delay_tolerance_ms }
   138→
   139→public(package) fun pyth_price_feeds(self: &XOracle): &Table<TypeName, PythFeedData> { 
   140→    dynamic_field::borrow(&self.id, PythPriceFeedKey {})
   141→}
   142→
   143→// mutable functions for admin purposes
   144→public(package) fun pyth_price_feeds_mut(self: &mut XOracle): &mut Table<TypeName, PythFeedData> { 
   145→    dynamic_field::borrow_mut(&mut self.id, PythPriceFeedKey {})
   146→}
   147→
   148→public(package) fun update_price_delay_tolerance_ms(self: &mut XOracle, price_delay_tolerance_ms: u64) {
   149→    assert!(price_delay_tolerance_ms <= MAX_DELAY_TOLERANCE_MS, oracle_error::invalid_delay_tolerance());
   150→    self.price_delay_tolerance_ms = price_delay_tolerance_ms;
   151→}
